{
  "scopeId": "GUARD-POLICY-01-WHOLE-TEXT",
  "role": "redteam",
  "scopeStatus": "COMPLETE",
  "wholeTextVote": "JA",
  "unconditional": true,
  "conditions": [],
  "requiredTextChanges": [],
  "sections": {
    "P1": {
      "status": "PASS_TEXT",
      "reason": "Prospektiver enger Gegenstand und Autoritaetshierarchie; keine Annahme von Entwurf01, Quellenwahrheit oder Umsetzung.",
      "evidence": [
        "proposal.md:2-4",
        "M/manifest.json#/status",
        "ADR0003:D6",
        "ADR0004:A5"
      ]
    },
    "P2": {
      "status": "PASS_TEXT",
      "reason": "Alle fuenf Guards unterscheiden gueltige negative Beobachtung, fehlende Kette und Invalidierung. Gemeinsames Veto vor lokaler Alternative; Guard und Fachwert gleiche passende Kette. Historien-/Hilfeanker und Materialprovenienz bleiben eigenstaendig, Musterunsicherheit wird nicht Beobachtungsunguelte. Keine pauschale Unterlassung enger belegter Aussagen.",
      "evidence": [
        "proposal.md:8-28",
        "M/catalogue.json#/facts",
        "ADR0003:D1-D5",
        "ADR0004:A1-A3"
      ]
    },
    "P3": {
      "status": "PASS_TEXT",
      "reason": "Fehlender Abschluss, invalidierte notwendige Bindung, protokollierte Abgabe und Vollstaendigkeit werden getrennt. Integritaetsvorrang, zeitbezogene Luecken und unverkuerzte all/none-/Fallbackregeln bleiben erhalten; SPECIFICATION_PENDING ist kein Fachwert.",
      "evidence": [
        "proposal.md:32-40",
        "M/CONTRACT.md:23-25,35-55,67-77",
        "M/rule-records.json#/0..7/logic/requires",
        "ADR0003:D2,D4"
      ]
    },
    "P4": {
      "status": "PASS_TEXT",
      "reason": "Definitive Ergebnisbasis ist eine ausdrueckliche neue Produktwahl, nicht Widerlegung der weiteren Architekturdefinition. Keine fachliche Fehlbewertung aus Automatik oder Lesart in irgendeinem Praefix. Gegenprobe bleibt nicht materialisiert und nicht ausgefuehrt.",
      "evidence": [
        "proposal.md:44-48",
        "H/didaktik/decision.json#/guardDefinitions/0",
        "H/architekt/decision.json#/guardDefinitions/0/values/wahr",
        "H/redteam/decision.json#/guardDefinitions/0",
        "ADR0003:D2.2"
      ]
    },
    "P5": {
      "status": "PASS_TEXT",
      "reason": "Sechs Originalfaelle, Inputs, Szenen und unveraenderte Oracles einschliesslich 30 Event- und 42 Hilfereferenzen gegengeprueft. C-HELP-ANCHOR und C-U07 bleiben getrennt offen; U07-Zuordnung setzt fehlendes Integritaetsveto voraus. Keine neue Gesamtoraclematrix oder Ein-Slot-Weltaktionsgrenze.",
      "evidence": [
        "proposal.md:52-59",
        "author/handoff.json#/caseIllustrations",
        "input-bindings.json#/selectedCases",
        "0005.projections.json"
      ]
    },
    "P6": {
      "status": "PASS_TEXT",
      "reason": "RT-GT-01 bis RT-GT-05 bleiben erhalten. Kontext-/Guardkatalog, CONTRACT 4/6 und alle acht Regelbindungen kontrolliert. Bestehende ADR-Ableitung, neue Produktpraezisierung und spaetere technische Integration werden getrennt. Keine Q-, M- oder Zusatzgate-Schliessung.",
      "evidence": [
        "proposal.md:63-67",
        "H/redteam/decision.json#/findings/0..4",
        "M/catalogue.json#/facts/0..2",
        "M/catalogue.json#/facts/17..21",
        "M/CONTRACT.md:43-55,67-77",
        "M/rule-records.json#/0..7/logic/requires"
      ]
    },
    "P7": {
      "status": "PASS_TEXT",
      "reason": "Exakte neue Ganztextvoten aller Rollen mit hoechstens zwei gleichzeitigen Kontexten, separate Auswertung/Ratifikation und danach eigenstaendiges vollstaendiges Manifest-Freeze-/Fremdreviewgate. Kein Teilvotum oder Dokumentvergleich ersetzt die Sperren.",
      "evidence": [
        "proposal.md:71-73",
        "ADR0003:D6",
        "ADR0004:90-98"
      ]
    }
  },
  "findings": [
    {
      "id": "RT4-T01",
      "severity": "INFO",
      "status": "NO_TEXT_CHANGE_REQUIRED",
      "finding": "Die definitive Ergebnisbasis verengt bewusst die Typgrenze; die historische Architekturgegenposition bleibt begruendet und wird nicht als widerlegt ausgegeben.",
      "evidence": [
        "proposal.md:44-48",
        "H/architekt/decision.json#/guardDefinitions/0/values/wahr"
      ]
    },
    {
      "id": "RT4-R01",
      "severity": "RETAINED_HIGH",
      "status": "OPEN_INTEGRATION_NOT_TEXT_CONDITION",
      "finding": "Die historischen D4-/Totalisierungs-/Kontextkonflikte werden durch Textzustimmung weder repariert noch geschlossen.",
      "evidence": [
        "proposal.md:63-67",
        "H/redteam/decision.json#/findings/0",
        "H/redteam/decision.json#/findings/1",
        "H/redteam/decision.json#/findings/2"
      ]
    },
    {
      "id": "RT4-R02",
      "severity": "RETAINED_MEDIUM",
      "status": "OPEN_INTEGRATION_NOT_TEXT_CONDITION",
      "finding": "U07-Hilfequellenkonflikt, Reportnormalform, eigene historische Hilfeanker sowie C-HELP-ANCHOR/C-U07 bleiben offen und getrennt.",
      "evidence": [
        "proposal.md:58-67",
        "H/redteam/decision.json#/findings/3",
        "H/redteam/decision.json#/findings/4"
      ]
    }
  ],
